Lemma rmrep_set_usage : forall st m sc v,
  rmrep st m -> 0 <= sc < 48 ->
  rmrep (set_usage sc v st) (write_to_mem m (wa (RCTX + 464 + 8 * sc)) (le8 (wz v))).
